  fighterPage=function(){let f=currentFighter();if(!f)return oldPage();init(f);let html=oldPage();if((f.freeSkill??f.free_skill)&&!f.skills.length)html=html.replace('No skills.','Starting skill missing.');if((f.subtypes||[f.type]).some(x=>promotionMap[x]))html=html.replace('<h2>Advancements</h2>',`<h2>Advancements</h2>${action('Promote','promote-fighter',f.id)}`);html=html.replace(/<div class="fighter-detail-stats">[\s\S]*?<\/div>/,statTable(f));html=html.replace('<span>☠ OOA:',`<button class="fp-ooa" data-fp="ooa-history" data-id="${f.id}">☠ OOA:`).replace(/(☠ OOA: [\d,]+)<\/span>/,'$1</button>');html=html.replace('>Heal</button>','>Delete</button>');if(isSpyrer(f)){html=html.replace('<h2>Lasting Injuries</h2>','<h2>Rig Glitches</h2>');html=html.replace('<h2>Fighter Notes</h2>',`<h2>Fighter Notes</h2>`);html=html.replace('<div class="fighter-status-actions">',`<p class="fp-glitch-count">Glitch Count: ${f.injuries.filter(x=>x.addsToGlitchCount).length} · Kills: ${fmt(f.killCount??f.kill_count)}</p>${action('Clear all rig glitches','clear-glitches',f.id)}<div class="fighter-status-actions">`);}html=html.replace(`<strong>${fmt(f.cost)}<small>Credits</small></strong>`,`<strong>${fmt(num(f.ratingCost??f.cost)+f.equipment.reduce((a,x)=>a+num(x.cost),0))}<small>Credits</small></strong>`);let creditMarkup=`<strong>${fmt(num(f.ratingCost??f.cost)+f.equipment.reduce((a,x)=>a+num(x.cost),0))}<small>Credits</small></strong>`;html=html.replace(creditMarkup,`<div class="fp-portrait-wrap"><button class="fp-portrait-button" data-fp="edit-image" data-id="${f.id}" aria-label="Edit Fighter Portrait" title="Edit Fighter Portrait">${portraitHTML(f)}</button>${creditMarkup}</div>`);let statusButtons=[['Dead','Kill Fighter','Resurrect Fighter'],['Retired','Retire Fighter','Unretire Fighter'],...(gang().edition==='N23'?[['Enslaved','Sell to Guilders','Release from Guilders']]:[]),['In Recovery','Send to Recovery','Recover Fighter'],['Captured','Capture Fighter','Rescue Fighter']].map(([status,label,undo])=>{let disabled=f.status!=='Active'&&f.status!==status;return `<button class="btn" data-${status==='Enslaved'?'fp="sell-fighter"':'parity="fighter-status"'} data-id="${f.id}" data-value="${status}" ${disabled?'disabled':''}>${f.status===status?undo:label}</button>`;}).join('');html=html.replace(/<div class="fighter-status-actions">[\s\S]*?<\/div><\/section>$/,`<div class="fighter-status-actions">${statusButtons}<button class="btn" data-ext="copy-fighter" data-id="${f.id}">Copy Fighter</button><button class="btn danger" data-parity="delete-fighter-page">Delete Fighter</button></div></section>`);if(isSpyrer(f)&&gang().edition==='N23')html=html.replace('<section><div class="section-heading"><h2>Fighter Notes</h2>',`<section><div class="section-heading"><h2>Power Boosts</h2>${action('Add','add-power-boost',f.id)}</div>${(f.powerBoosts||[]).map(x=>`<div class="mini-row"><span>${esc(x.name)} · ${num(x.killCost)} kills · ${num(x.cost)} credits</span>${action('Undo','undo-power-boost',f.id,x.id)}</div>`).join('')||'<p class="muted">No power boosts.</p>'}</section><section><div class="section-heading"><h2>Fighter Notes</h2>`);for(let injury of f.injuries)if(injury.hatredTargetName)html=html.replace(`<span>${esc(injury.name)}</span>`,`<span>${esc(injury.name)} (${esc(injury.hatredTargetName)})</span>`);for(let name of f.skills){let details=f.skillDetails.filter(x=>x.name===name);let index=f.skills.indexOf(name),locked=details.some(x=>x.injuryId||x.sourceEquipmentId)||f.advancements.some(x=>x.kind==='Skill'&&x.name===name);if(locked)html=html.replace(`data-ext="remove-skill" data-id="${f.id}" data-sub="${index}"`,`data-ext="remove-skill" data-id="${f.id}" data-sub="${index}" disabled`);if(details.length)html=html.replace(`<td>${esc(name)}</td><td>Fighter</td>`,`<td>${esc(name)}</td><td>${details.map(x=>esc(x.source||'Fighter')+(x.hatredTargetName?' · '+esc(x.hatredTargetName):'')).join(', ')}</td>`);}if(f.specialRules.length)html=html.replace(statTable(f),statTable(f)+`<p class="fp-special-rules">${f.specialRules.map(esc).join(' · ')}</p>`);return html;};
  function rollD6(){let a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]%6+1;}
  window.addEventListener('click',e=>{let t=e.target.closest('[data-fp],[data-add-skill],[data-ext="copy-fighter"],[data-ext="remove-skill"],[data-play="remove-advancement"],[data-play="heal-injury"],[data-parity="fighter-status"],[data-parity="delete-fighter-page"],[data-delete-fighter],[data-equipment-remove],[data-to-stash]');if(!t)return;let d=t.dataset,fid=d.id||d.addSkill||d.deleteFighter||d.toStash?.split(':')[0]||d.equipmentRemove?.split(':')[0]||data.selectedFighter,f=gang()?.fighters.find(x=>x.id===fid);if(!f&&d.fp==='equipment-buy'){e.preventDefault();e.stopImmediatePropagation();let a=catalogue('equipment').find(x=>uidOf(x)===d.sub);if(a)purchaseEquipment(null,a,true);return;}if(!f)return;init(f);e.preventDefault();e.stopImmediatePropagation();if(d.addSkill)return addSkill(f);if(d.ext==='copy-fighter')return copyFighter(f);if(d.ext==='remove-skill')return deleteSkill(f,num(d.sub));if(d.play==='remove-advancement')return removeAdvancement(f,d.sub);if(d.play==='heal-injury'){let injury=f.injuries.find(x=>x.id===d.sub);return modal('Delete Lasting Injury',`<p>Are you sure you want to delete ${esc(injury?.name||'this injury')}?</p>`,'Delete',()=>{removeInjury(f,d.sub);save();});}if(d.parity==='delete-fighter-page'||d.deleteFighter)return deleteFighter(f);if(d.parity==='fighter-status'){if(d.value)return changeStatus(f,f.status===d.value?'Active':d.value);return modal('Change Status',combo('status','Status',['Active','In Recovery','Captured','Retired','Dead','Enslaved','Starved'],f.status),'Confirm',v=>{f.status=v.status;save();});}if(d.toStash){let eid=d.toStash.split(':')[1],item=f.equipment.find(x=>x.id===eid);return modal('Move Equipment to Stash',`<p>Move ${esc(item.name)} to the gang stash?</p>`,'Move',()=>{gang().stash.push(item);f.equipment=f.equipment.filter(x=>x.id!==eid);f.loadouts.forEach(l=>l.equipmentIds=l.equipmentIds.filter(x=>x!==eid));save();});}if(d.equipmentRemove){let eid=d.equipmentRemove.split(':')[1];return modal('Delete Equipment','<p>Delete this equipment?</p>','Delete',()=>{f.equipment=f.equipment.filter(x=>x.id!==eid);save();});}
  switch(d.fp){case 'edit-image':portraitEditor(f);break;case 'choose-image':$('#fp-portrait-file').click();break;case 'remove-image':f.imageUrl='';f.image_url='';delete f.portraitCrop;log(gang(),`${f.name}: portrait removed`);save();portraitEditor(f);break;case 'add-power-boost':addPowerBoost(f);break;case 'undo-power-boost':undoPowerBoost(f,d.sub);break;case 'power-boost-roll':{let rolled=rollD6(),boost=ruleList('effects').find(x=>x.category==='power-boosts'&&titleOf(x)===powerBoostRolls[rolled-1]);$('#fp-boost-roll').textContent=`Roll ${rolled}: ${boost?titleOf(boost):''}`;if(boost){$('#modal-form').elements.boost.value=boost.id;$('#modal-form').elements.boost.dispatchEvent(new Event('change',{bubbles:true}));}break;}case 'promote-fighter':promoteFighter(f);break;case 'promotion-add-rule':{readPromotion();let rule=$('#modal-form').elements.newRule.value.trim();if(rule&&!promotionDraft.rules.includes(rule))promotionDraft.rules.push(rule);promoteFighter(f,promotionDraft);break;}case 'promotion-remove-rule':readPromotion();promotionDraft.rules.splice(num(d.sub),1);promoteFighter(f,promotionDraft);break;case 'clear-glitches':clearRigGlitches(f);break;case 'clear-glitches-kills':clearRigGlitches(f,'kills');break;case 'clear-glitches-downtime':clearRigGlitches(f,'downtime');break;case 'add-rule':{collectDraft(f);let value=$('#modal-form').elements.nextRule.value.trim();if(value&&!editDraft.specialRules.includes(value))editDraft.specialRules.push(value);openEdit(f,editDraft);break;}case 'remove-rule':collectDraft(f);editDraft.specialRules.splice(num(d.sub),1);openEdit(f,editDraft);break;case 'add-subtype':{collectDraft(f);let value=$('#modal-form').elements.nextSubtype.value;if(value&&!editDraft.subtypes.includes(value))editDraft.subtypes.push(value);openEdit(f,editDraft);break;}case 'remove-subtype':collectDraft(f);editDraft.subtypes.splice(num(d.sub),1);openEdit(f,editDraft);break;case 'adjust-stats':collectDraft(f);editStats({...f,stats:editDraft.stats},true);break;case 'skill-access':collectDraft(f);skillAccess(f);break;case 'stat-minus':case 'stat-plus':{let input=$('#modal-form').elements['stat_'+d.sub];input.value=num(input.value)+(d.fp==='stat-plus'?1:-1);break;}case 'xp-minus':case 'xp-plus':{let input=$('#modal-form').elements['count_'+d.sub];input.value=Math.max(0,num(input.value)+(d.fp==='xp-plus'?1:-1));updateXp();break;}case 'advance-roll':{let a=rollD6(),b=rollD6(),total=a+b,form=$('#modal-form');$('#fp-advance-roll').textContent=`${a} + ${b} = ${total}`;if(form.elements.band){let bands=advanceBands[gang().edition==='N26'?'N26':'N23'],index=bands.findIndex(row=>total>=row.min&&total<=row.max);form.elements.band.value=String(index);window.MMWidgets?.sync(form.elements.band);showAdvanceBand(f);}else{form.elements.kind.value='Characteristic';window.MMWidgets?.sync(form.elements.kind);advanceFields(f);}log(gang(),`${f.name}: rolled advancement ${total}`);save();break;}case 'skill-roll':{let form=$('#modal-form'),list=advancementSkills(form.elements.skillSet.value).filter(x=>!f.skills.includes(titleOf(x)));if(list.length){let bytes=new Uint32Array(1);crypto.getRandomValues(bytes);form.elements.skill.value=uidOf(list[bytes[0]%list.length]);window.MMWidgets?.sync(form.elements.skill);log(gang(),`${f.name}: rolled skill ${titleOf(list[bytes[0]%list.length])}`);save();}break;}case 'injury-roll':{let a=rollD6(),b=rollD6(),value=a*10+b,list=injuryList(),injury=list.find(x=>value>=num(x.min??x.type_specific_data?.d66_min)&&value<=num(x.max??x.type_specific_data?.d66_max));$('#fp-injury-roll').textContent=`${value}${injury?': '+titleOf(injury):''}`;if(injury){$('#modal-form').elements.injury.value=uidOf(injury);$('#modal-form').elements.injury.dispatchEvent(new Event('change',{bubbles:true}));}log(gang(),`${f.name}: rolled D66 ${value}${injury?' — '+titleOf(injury):''}`);save();break;}case 'loadout-select':openLoadouts(f,d.sub||null);break;case 'loadout-create':{let name=$('#modal-form').elements.name.value.trim();if(name){let l={id:id(),name,equipmentIds:[],active:loadoutDraft.length===0};loadoutDraft.push(l);openLoadouts(f,l.id);}break;}case 'loadout-active':loadoutDraft.forEach(x=>x.active=x.id===d.sub);openLoadouts(f,d.sub);break;case 'loadout-delete':{let selected=d.sub,form=modal('Delete Loadout','<p>Are you sure you want to delete this loadout?</p>','Delete',()=>{loadoutDraft=loadoutDraft.filter(x=>x.id!==selected);setTimeout(()=>openLoadouts(f,null),0);});returnOnCancel(form,()=>openLoadouts(f,selected));break;}case 'loadout-rename':{let l=loadoutDraft.find(x=>x.id===d.sub);let form=modal('Edit Loadout',field('name','Loadout name',l.name,'text','required maxlength="50"'),'Save',v=>{l.name=v.name.trim();setTimeout(()=>openLoadouts(f,l.id),0);});returnOnCancel(form,()=>openLoadouts(f,l.id));break;}case 'equipment-buy':{let a=equipmentFor(f,$('#modal-form')?.elements.list?.value||'all').find(x=>uidOf(x)===d.sub),stash=$('#modal-form')?.dataset.stash==='yes';purchaseEquipment(f,a,stash);break;}case 'equipment-detail':equipmentDetail(f,f.equipment.find(x=>x.id===d.sub));break;case 'sell-fighter':sellFighter(f);break;case 'ooa-history':ooaHistory(f);break;case 'ooa-tab':ooaHistory(f,d.sub);break;case 'ooa-add':ooaRecordForm(f);break;case 'ooa-edit':ooaRecordForm(f,f.ooaRecords.find(x=>x.id===d.sub));break;case 'ooa-delete':modal('Delete Record','<p>Are you sure you want to delete this record?</p>','Delete',()=>{f.ooaRecords=f.ooaRecords.filter(x=>x.id!==d.sub);save();setTimeout(()=>ooaHistory(f),0);});break;}
  },true);
  // Links on equipment names expose the purchased profile and editable item cost.
  const oldRender=render;render=function(){oldRender();if(data.view!=='fighter')return;let f=currentFighter();if(!f)return;document.querySelectorAll('.fighter-page table tbody tr').forEach(row=>{let cell=row.querySelector('td');if(!cell)return;let item=f.equipment.find(x=>x.name===cell.textContent.trim());if(item){cell.innerHTML=`<button class="fp-text-link" data-fp="equipment-detail" data-id="${f.id}" data-sub="${item.id}">${esc(item.name)}</button>`;let active=f.loadouts.find(l=>l.active);if(active&&!active.equipmentIds.includes(item.id))row.hidden=true;}});};
  window.FighterParity={init,stats,openEdit,addSkill,copyFighter,sellFighter,changeStatus,deleteFighter,purchaseEquipment,injuryList,clearRigGlitches,removeInjury,equipmentProfiles,promoteFighter,deleteSkill,addPowerBoost,undoPowerBoost,portraitEditor,portraitSource};
